): string => {
    const buildAppealPointInstructions = (rules: AppealPointInstruction[]): string => {
        if (rules.length === 0) {
            return '指示なし';
        }
        const instructions = rules
            .map(rule => {
                const instruction = rule.customInstruction.trim() || 'インタビュー内容に基づいて、このアピールポイントを魅力的に説明してください。';
                return `■ ${rule.pointName}\n指示: ${instruction}`;
            }).join('\n\n');

        return `以下の各アピールポイントについて、指定された指示に従って詳細な説明を作成してください:\n\n${instructions}`;
    };

    const appealPointsContent = buildAppealPointInstructions(appealPointRules);

    const appealPointsInstruction = `
