---
${appealPointsContent}
---
`;

    const companyInfoContent = companyInfo.trim()
        ? `
# 事前に収集した企業情報 (補足用)
---
${companyInfo}
---
`
        : '';

    const sampleMessageSection = sampleMessage.trim()
        ? `
