const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Retry Helper
const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

async function retryOperation<T>(
    operation: () => Promise<T>, 
    maxRetries: number = 5, 
    initialDelay: number = 2000
): Promise<T> {
    let lastError: any;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
            return await operation();
        } catch (error: any) {
            lastError = error;

            // Analyze error to see if it's retryable (Quota limits or Server errors)
            // Error structure seen: {"error":{"code":429,"message":"...","status":"RESOURCE_EXHAUSTED"}}
            const status = error.status || error.code || error.response?.status;
            const message = error.message || JSON.stringify(error);

            const isQuotaError = status === 429 || 
                                 status === 'RESOURCE_EXHAUSTED' || 
                                 message.includes('429') || 
                                 message.includes('RESOURCE_EXHAUSTED') ||
                                 message.includes('quota');

            const isServerError = (typeof status === 'number' && status >= 500 && status < 600) || 
                                  message.includes('503') || 
                                  message.includes('500');

            if (attempt < maxRetries && (isQuotaError || isServerError)) {
                // Exponential backoff with jitter: 2s, 4s, 8s, 16s, 32s...
                const delay = initialDelay * Math.pow(2, attempt) + (Math.random() * 1000);
                console.warn(`Gemini API Request failed (Attempt ${attempt + 1}/${maxRetries + 1}). Retrying in ${Math.round(delay)}ms... Error: ${message}`);
                await sleep(delay);
                continue;
            }

            // Not retryable or max retries reached
            throw error;
        }
    }
    throw lastError;
}

