interface GenerationResult {
    text: string;
    sources: { uri: string; title: string }[];
}

export const generateJobDescription = async (
    interviewLog: string, 
    companyInfo: string,
    templateInstructions: string, 
    sampleMessage: string,
    appealPointRules: AppealPointInstruction[],
    recruitmentTemplates: string,
    catchphraseTemperature: number,
    manuscriptTemperature: number
): Promise<GenerationResult> => {
  try {
    const model = 'gemini-2.0-flash';

    // Step 1: Generate Catchphrases
    const catchphrasePrompt = buildCatchphrasePrompt(interviewLog, companyInfo);

    // Wrapped in retry logic
    const catchphraseResponse = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
        model,
        contents: { parts: [{ text: catchphrasePrompt }] },
        config: { temperature: catchphraseTemperature }
    }));

    const generatedCatchphrases = catchphraseResponse.text || '';

    // Step 2: Generate the rest of the manuscript
    const manuscriptPrompt = buildManuscriptPrompt(
        interviewLog, 
        companyInfo, 
        templateInstructions, 
        sampleMessage,
        appealPointRules, 
        recruitmentTemplates,
        generatedCatchphrases
    );

    // Wrapped in retry logic
    const manuscriptResponse = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
        model,
        contents: { parts: [{ text: manuscriptPrompt }] },
        config: { temperature: manuscriptTemperature }
    }));

    const sources = manuscriptResponse.candidates?.[0]?.groundingMetadata?.groundingChunks
        ?.map(chunk => chunk.web)
        .filter(web => web?.uri && web.title) as { uri: string; title: string }[] || [];

    // The final text is the manuscript, which should include the catchphrases.
    return { text: manuscriptResponse.text || '', sources };
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    if (error instanceof Error) {
        throw new Error(`Gemini API Error: ${error.message}`);
    }
    throw new Error("An unexpected error occurred while calling the Gemini API.");
  }
};

export const refineJobDescription = async (
    currentDescription: string,
    instruction: string,
    temperature: number,
    recruitmentTemplates?: string,
    tone: number = 50
): Promise<string> => {
    const model = 'gemini-2.0-flash';

    // Logic for Tone Adjustment
    let toneInstruction = "";
    if (tone !== 50 && recruitmentTemplates) {
        const direction = tone < 50 ? "カジュアル・柔らか・親しみやすい" : "堅実・フォーマル・論理的";
        const intensity = Math.abs(tone - 50) * 2; // Scale difference to 0-100% intensity

        toneInstruction = `
        **Tone Adjustment Task:**
        The user wants to adjust the tone of the manuscript.
